333	  // Marca pendente->vencida, gera faturas de todo período fechado ainda não
334	  // faturado, e devolve o status atual de bloqueio da loja.
335	  // forcar=true também gera fatura do período atual mesmo que ainda não tenha
336	  // fechado (usado pelo botão "Renovar agora"/"Gerar fatura" sob demanda).
337	  async sincronizarPeriodo(titular: Titular, forcar = false) {
338	    const assinatura = await this.buscarAssinaturaRaw(titular);
339	    if (!assinatura || assinatura.status === 'cancelada') {
340	      return { bloqueado: false, dias_atraso: 0, fatura_pendente_id: null, plano_nome: null, proxima_cobranca: null };
341	    }
342	
343	    const agora = new Date();
344	    const plano = assinatura.planos;
345	    const meses = MESES_POR_PERIODICIDADE[plano.periodicidade] ?? 1;
346	
347	    // Marca vencidas
348	    await this.supabase.client
349	      .from('plano_faturas')
350	      .update({ status: 'vencida', atualizado_em: agora.toISOString() })
351	      .eq('assinatura_id', assinatura.id)
352	      .eq('status', 'pendente')
353	      .lt('vencimento', agora.toISOString());
354	
355	    // Gera períodos fechados pendentes de fatura (+ o período atual se forcar=true)
356	    let inicioPeriodo = assinatura.ultimo_periodo_faturado_fim
357	      ? new Date(assinatura.ultimo_periodo_faturado_fim)
358	      : new Date(assinatura.data_inicio);
359	    let ultimoFimFaturado = assinatura.ultimo_periodo_faturado_fim
360	      ? new Date(assinatura.ultimo_periodo_faturado_fim)
361	      : null;
362	
363	    // Se já existe fatura pendente/vencida/isenta de QUALQUER período, "Renovar
364	    // agora" não pode gerar outra. Isenta entra aqui também — senão clicar de
365	    // novo (a fatura isenta não bloqueia "pendente/vencida") empurra a cobrança
366	    // pro período seguinte a cada clique, gerando várias faturas de R$0 em
367	    // sequência.
368	    let temPendenteAberta = false;
369	    if (forcar) {
370	      const { data: pendenteExistente, error: pendErroCheck } = await this.supabase.client
371	        .from('plano_faturas')
372	        .select('id')
373	        .eq('assinatura_id', assinatura.id)
374	        .in('status', ['pendente', 'vencida', 'isenta'])
375	        .is('plano_id_troca', null)
376	        .limit(1)
377	        .maybeSingle();
378	      if (pendErroCheck) throw pendErroCheck;
379	      temPendenteAberta = !!pendenteExistente;
380	    }
381	
382	    // eslint-disable-next-line no-constant-condition
383	    while (true) {
384	      const fimPeriodo = somarMeses(inicioPeriodo, meses);
385	      const periodoFechado = fimPeriodo < agora;
386	      if (!periodoFechado && !forcar) break;
387	
388	      if (!periodoFechado) {
389	        if (temPendenteAberta) break;
390	
391	        // Período em aberto forçado: se já existe fatura pra esse período (de um
392	        // "Renovar agora" anterior), não gera outra nem avança o ciclo de novo —
393	        // senão cada clique empurraria a cobrança um mês pra frente.
394	        const { data: jaExiste, error: existeErro } = await this.supabase.client
395	          .from('plano_faturas')
396	          .select('id')
397	          .eq('assinatura_id', assinatura.id)
398	          .eq('periodo_inicio', inicioPeriodo.toISOString())
399	          .maybeSingle();
400	        if (existeErro) throw existeErro;
401	        if (jaExiste) break;
402	      }
403	
404	      // Isenção por piso de faturamento só existe pro SaaS — instalação local
